# -*- coding: utf-8 -*-
# src/utils/hooks.ts 的批注数据（第 45 批之一）
# Hook 执行引擎：命令/提示/代理/HTTP/回调五类 hook 的匹配、执行、输出解析与结果聚合

ANNOTATIONS = [
    (1, 'after', r'''文件头。本文件是 Claude Code Hook 系统的执行引擎——hook 是用户在 settings.json 里配置的 shell 命令（或提示词/代理/HTTP 请求/SDK 回调），在生命周期各节点（工具调用前后、会话起止、压缩、通知等）被自动触发。全文件围绕三条主线：① 找出该事件下匹配的 hook（getMatchingHooks，含 matcher 模式、if 条件、去重）；② 真正执行它们（execCommandHook 派生子进程，executeHooks 聚合并行结果）；③ 解析输出并翻译成内部行为（进程退出码协议 + JSON 输出协议）。'''),
    (166, 'after', r'''全局默认超时：10 分钟。单个 hook 可用配置里的 timeout（秒）覆盖；这个值同时充当无配置 hook 的默认超时与总 AbortSignal 上限。'''),
    (182, 'after', r'''读取会话结束 hook 的超时：默认仅 1500ms——SessionEnd 在关机/清屏路径上跑，必须比工具类 hook 紧得多。可用环境变量 CLAUDE_CODE_SESSIONEND_HOOKS_TIMEOUT_MS 覆盖，照顾收尾脚本慢的用户。'''),
    (184, 'before', r'''异步 hook 的后台化执行。两条路：asyncRewake 模式完全绕开注册表，靠任务通知唤醒模型；普通 async 模式走 registerPendingAsyncHook 注册，完成后由注册表收割。'''),
    (217, 'after', r'''asyncRewake 分支的关键权衡：故意不调 shellCommand.background()——那会把 TaskOutput 落盘，破坏内存态的 stdout/stderr 捕获（落盘后 getStderr 返回空串）。流包装器保持挂载，数据持续灌进内存缓冲。中断语义分两档：用户发新消息（interrupt）时 abort 处理器直接空操作，hook 活下来；硬取消（Esc）才会杀掉 hook。'''),
    (265, 'after', r'''executeInBackground 收尾：注册表路径调用 shellCommand.background(processId) 把进程挂到后台管理器，再登记进 AsyncHookRegistry；失败（如进程已退出）返回 false，调用方会回退到同步等待。'''),
    (286, 'before', r'''信任门禁：所有 hook 都要求工作区信任。这是纵深防御——hook 会执行 settings.json 里的任意命令。注释里记录了两个曾真实出现的历史漏洞：SessionEnd hook 在用户拒绝信任弹窗时执行、SubagentStop hook 在信任前执行。'''),
    (296, 'after', r'''判定规则：非交互模式（SDK）信任是隐含的，直接放行；交互模式统一查信任弹窗是否已接受，没接受就跳过。集中放在一处，防止未来新增事件时漏掉检查。'''),
    (328, 'after', r'''createBaseHookInput：所有 hook 输入的公共底座——session_id、transcript_path（指向本会话的 JSONL 转录文件）、cwd、permission_mode，外加 agent_id/agent_type 区分子代理调用。注意 agent_type 的优先级：子代理自身类型覆盖主线程的 --agent 标志。'''),
    (333, 'after', r'''HookBlockingError：阻塞错误 = 给模型的反馈文本 + 触发它的命令。'''),
    (336, 'after', r'''把 MCP SDK 的 ElicitResult 原样重导出为 ElicitationResponse，兼容旧引用。'''),
    (357, 'after', r'''HookResult：单个 hook 的执行结果，字段非常多——message/systemMessage/blockingError 是常规三件套；additionalContext 注入上下文；initialUserMessage 顶替首条用户消息；updatedInput 改写工具入参；updatedMCPToolOutput 替换 MCP 工具输出；watchPaths 声明要监听的文件；retry 要求权限被拒后重试；elicitation 系列响应 MCP 引导。'''),
    (376, 'after', r'''AggregatedHookResult：多个 hook 结果归并后的形态（对比 HookResult 少了 hook 自身，多了 hookSource 来源标记，additionalContext 变复数）。调用方消费的就是这个形状。'''),
    (382, 'before', r'''用 Zod schema 校验 hook 的 JSON 输出。失败时把每条 issue 拼成多行错误串，附上原始输出方便排查。'''),
    (399, 'before', r'''parseHookOutput：命令 hook stdout 的解析入口。不以花括号开头 → 当纯文本；是 JSON 但校验失败 → 错误信息里附带期望 schema 的完整示例（这段 schema 文档是给 hook 作者看的报错教材）；JSON 解析本身抛异常 → 回退纯文本。'''),
    (451, 'after', r'''parseHookOutput 收尾：plainText 分支让旧式 hook（只 echo 文本）继续工作——退出码 0 时文本进 hook_success 附件，退出码 2 时 stderr 阻塞，这是 JSON 协议之前的原始约定。'''),
    (453, 'before', r'''parseHttpHookOutput：HTTP hook 的响应体解析。与命令版两处不同：空响应体按空对象 {} 校验（等价于「无操作」）；非 JSON 响应直接报验证错误而不是降级纯文本——HTTP 没有「退出码」可依赖，必须强制 JSON 协议。'''),
    (487, 'after', r'''parseHttpHookOutput 收尾：非花括号开头、校验失败、JSON 异常三种情况都返回 validationError，调用方据此产出 non_blocking_error。'''),
    (489, 'before', r'''processHookJSONOutput：把校验过的 sync JSON 翻译成 Partial<HookResult>。这里是整个 JSON 输出协议的语义中心——continue:false 停止回合、decision approve/block 控制、hookSpecificOutput 按事件名分派十几种特化字段。'''),
    (543, 'after', r'''旧协议 decision 字段：approve → 放行、block → 拒绝并构造 blockingError（理由缺省「Blocked by hook」）。未知值直接抛错而不是忽略——fail fast，防止 hook 作者拼错字段后静默失效。'''),
    (575, 'after', r'''PreToolUse 的顶层 permissionDecision（hookSpecificOutput 外层简写版）：allow/deny/ask 三态，deny 同样带 blockingError。这段和 593 行 switch 里的同名分支功能重叠——新版协议把决策放进 hookSpecificOutput，这里先兜旧写法。'''),
    (578, 'after', r'''只要产生了权限行为且 reason 存在，就记录 hookPermissionDecisionReason——这个 reason 最终会显示在权限弹窗里，向用户解释 hook 为什么放行/拒绝。'''),
    (592, 'before', r'''按事件名分派特化输出。每个事件能携带的字段不同：PreToolUse 可改入参，UserPromptSubmit/SessionStart/SubagentStart 注入上下文，PostToolUse 可改写 MCP 工具输出，PermissionDenied 可要求重试，PermissionRequest 可代答权限，Elicitation 系列可代答 MCP 引导。'''),
    (708, 'after', r'''事件分派收尾。注意 expectedHookEvent 校验在前面 584 行：hook 报告的事件名必须与实际触发的事件一致，防止一个 UserPromptSubmit hook 的输出被误当成 PreToolUse 决策。'''),
    (737, 'after', r'''最后统一构造 message 附件：有 blockingError 用 hook_blocking_error，否则 hook_success——且 success 分支的 content 固定传空串，因为 JSON hook 的上下文注入走 additionalContext 通道，这里再塞 stdout 会每回合刷一条「X hook success: Success」的无聊系统提醒（见 messages.ts:3577 的跳过逻辑）。'''),
    (747, 'before', r'''execCommandHook：命令型 hook 的实际执行器，全文件最长的函数（约 590 行）。shell 解析顺序 hook.shell → 默认 bash；PowerShell hook 用 pwsh -NoProfile -NonInteractive -Command 显式 argv 派生，并跳过所有 bash 专属准备（POSIX 路径转换、.sh 自动前缀、SHELL_PREFIX 包装）。'''),
    (790, 'after', r'''每 hook 级 shell 选择（ps-shell-selection 设计文档第一阶段）：hook.shell 优先，回落 DEFAULT_HOOK_SHELL。settings 里的 defaultShell 全局回落是第二阶段，尚未接线。'''),
    (811, 'after', r'''路径转换器 toHookPath 的分岔：Windows + bash 时走 windowsPathToPosixPath（纯 JS 正则转换 C:/Users/foo → /c/Users/foo，LRU-500 记忆化，不 shell 出 cygpath）；PowerShell 路径保持原样——pwsh 在 Windows 上要的就是原生 C 盘风格路径。根因：hook 在 Windows 上经 Git Bash（Cygwin）跑，Git Bash 解析不了 Windows 路径。'''),
    (816, 'after', r'''CLAUDE_PROJECT_DIR 取稳定的工程根而非 worktree 路径——getProjectRoot() 进入 worktree 时从不更新，所以 hook 里引用这个变量的脚本永远解析到真仓库根。'''),
    (857, 'after', r'''命令串里的模板变量替换：先插件变量（CLAUDE_PLUGIN_ROOT/CLAUDE_PLUGIN_DATA）再用户配置 ${user_config.X}，顺序与 MCP/LSP 一致，保证用户填的字面量 ${CLAUDE_PLUGIN_ROOT} 被当不透明文本。插件目录不存在的预检查很关键：缺脚本时 python3 会退出码 2——那是 hook 协议的「阻塞」码，会被误读成有意阻塞，把 UserPromptSubmit/Stop 卡死到重启。'''),
    (866, 'after', r'''Windows bash 路径下 .sh 脚本自动补 bash 前缀，否则会被交给默认文件处理器「打开」而不是执行。PowerShell 跑 .ps1 天经地义，无需前缀。'''),
    (875, 'after', r'''CLAUDE_CODE_SHELL_PREFIX 用 POSIX 引号包装命令（shell-quote 实现），对 PowerShell 无意义——PS hook 暂时忽略该前缀，shell 感知的前缀是后续工作。'''),
    (885, 'after', r'''环境变量底座：继承子进程环境 + CLAUDE_PROJECT_DIR（全部经 toHookPath 转换）。'''),
    (906, 'after', r'''插件选项同时以环境变量暴露（CLAUDE_PLUGIN_OPTION_XXX，键名清洗成合法标识符并大写）——hook 可以不写 ${user_config.X} 直接读环境变量。敏感值也包含在内：hook 本来就跑用户自己的代码，与直接读钥匙串同一条信任边界。'''),
    (926, 'after', r'''CLAUDE_ENV_FILE 只发给四个会话级事件（SessionStart/Setup/CwdChanged/FileChanged）：hook 往这个 .sh 文件写环境变量定义，后续由 bashProvider 拼接注入。PS hook 跳过——它写的是 PS 语法（$env:FOO），bash 解析不了。'''),
    (938, 'after', r'''cwd 安全兜底：agent 的 worktree 被删后 getCwd() 可能经 AsyncLocalStorage 返回已删除路径。spawn 对缺失 cwd 是异步报 error 事件而非同步抛错，所以必须在派生前验证，失败回落原始 cwd。'''),
    (984, 'after', r'''两条完全独立的派生路径：bash 走 spawn(cmd, [], {shell})（shell 选项让 Node 把整串交给 shell 解析，Windows 上显式用 Git Bash，因为 cmd.exe 跑不了 bash 语法）；PowerShell 走显式 argv，-NoProfile 跳过用户配置脚本（更快更确定），-NonInteractive 遇到要提示时快速失败。windowsHide 防止 Windows 弹黑框。'''),
    (1008, 'after', r'''配置级 async hook 后台化前先把 stdin 写完——结尾换行符不可省：bash 的 read -r line 没有分隔符会返回退出码 1，变量其实有值但 if read 分支被跳过（gh-30509 / CC-161）。'''),
    (1030, 'after', r'''配置级 async（hook.async 或 asyncRewake 且未被强制同步）：写完输入立即后台化并返回 backgrounded:true，外层据此跳过输出收集。'''),
    (1062, 'after', r'''processedPromptLines 记录已处理过的提示请求行（按内容匹配而非下标——没有下标漂移问题），close 时从最终 stdout 里剔除，保证 prompt JSON 永远不会泄漏进 hook 结果解析。'''),
    (1116, 'after', r'''异步检测协议：hook 的第一行输出若是 {async:true,...} 形状的 JSON 就转后台。必须只解析第一行——进程够快时整个 stdout 可能已经积累完，解析全量会失败，异步 hook 就会白白阻塞满时长。'''),
    (1165, 'after', r'''stdout 数据处理收尾。三件事：累积输出；有 requestPrompt 时逐行探测提示请求（promptRequestSchema 校验通过就串行询问用户并把响应写回 hook 的 stdin，失败就销毁 stdin 防止 hook 挂等）；首行异步检测。promptChain 串行化保证响应按序写出。'''),
    (1216, 'after', r'''stdin 写入带 EPIPE 处理：hook 命令没读完输入就退出时会写失败。有 requestPrompt 时 stdin 保持打开（后续要写响应），此时 EPIPE 属预期，只记日志不拒绝。'''),
    (1260, 'after', r'''close  promise：退出码空值视为 1；解析要等 stdout/stderr 两个流的 end 事件都到齐再返回，防止 close 先于最后一批 data 触发的竞态。返回前剔除已处理的提示请求行。'''),
    (1282, 'after', r'''三路竞速：stdin 写入、异步检测转后台（childIsAsyncPromise）、进程正常关闭，任一先行。等结果返回前还要 await promptChain，确保排队的提示响应全部写完。'''),
    (1335, 'after', r'''execCommandHook 收尾与错误分类：EPIPE（hook 提前关 stdin）与 ABORT_ERR（用户取消）各有专用返回；finally 里发出 completed 诊断标记（与 started 配对，半途抛错时会孤儿化 started 标记——那与挂死无法区分，所以 started/completed 都在 try/finally 里）、停进度定时器；shellCommand 所有权已转移（转给异步注册表）时不再 cleanup。'''),
    (1346, 'before', r'''matcher 模式匹配：空串或 * 全过；仅含字母数字下划线竖线的按精确/竖线分隔匹配（先归一化旧工具名）；其余当正则（无效正则记日志返回 false，不抛）。正则还会对旧工具名各测一遍，让 ^Task$ 这类旧模式继续命中。'''),
    (1381, 'after', r'''matchesPattern 收尾。设计取向：宁可宽松也要向后兼容——旧工具名（Task→Agent 之类改名）在精确匹配与正则两条路上都被兼容。'''),
    (1390, 'before', r'''if 条件匹配器的「预编译」：昂贵的部分（工具查找、Zod 校验、Bash 的 tree-sitter 解析）只做一次，返回的闭包给每个 hook 反复调用。仅工具类事件（PreToolUse/PostToolUse/PostToolUseFailure/PermissionRequest）有意义。'''),
    (1421, 'after', r'''闭包逻辑：if 条件形如 Bash(git *)——先比对工具名，无规则内容即通过，有则交给工具自带的 permissionMatcher（如 Bash 用 git 前缀树匹配）。不匹配的 hook 在派生进程前就被过滤，省一次进程启动开销。'''),
    (1442, 'after', r'''isInternalHook：internal 回调（sessionFileAccessHooks、attributionHooks 等系统内置）不算用户 hook，走统计与遥测时会剔除。'''),
    (1455, 'after', r'''去重键按来源上下文分命名空间：settings hook（无插件/技能根）共享空前缀——同一命令在 user/project/local 重复定义仍合并成一条（去重的本意）；插件/技能 hook 用各自的根做前缀——两个插件写了同一个未展开模板 ${CLAUDE_PLUGIN_ROOT}/hook.sh 不会被误合并，展开后指向的是不同文件。'''),
    (1478, 'after', r'''getPluginHookCounts：遥测统计各插件的 hook 数。只记录官方市场的真名，第三方一律聚合成 third-party——避免把用户装了什么插件泄漏进分析数据。'''),
    (1490, 'after', r'''getHookTypeCounts：按 hook 类型（command/prompt/agent/http/callback/function）计数，进 tengu_run_hook 遥测。'''),
    (1492, 'before', r'''getHooksConfig：把同一事件的 hook 从三个来源依序合并——① 管理快照（settings 文件的 HookMatcher，zod 剥离后可直接推送）；② 注册的 hook（SDK 回调 + 插件原生 hook）；③ 会话级 hook（含 function hook，只能按会话隔离，防止一个代理的 hook 泄漏给另一个）。'''),
    (1566, 'after', r'''getHooksConfig 收尾与两道安全闸：managedOnly（企业策略只允许受管 hook）时插件 hook 和会话 hook 全部跳过——后者防止 agent/skill 的 frontmatter hook 绕过策略；strictPluginOnlyCustomization 不在这里一刀切，而是在注册点按来源精确把关，否则插件自带 agent 的 frontmatter hook 也会被误杀。'''),
    (1582, 'before', r'''hasHookForEvent：轻量存在性检查，镜像 getHooksConfig 的来源但命中即停。故意过近似——matcher 存在但后续会被过滤也返回 true（假阳性只是多走一遍完整匹配，假阴性会漏执行 hook）。用在热点路径上跳过 transcript 路径拼接等昂贵操作。'''),
    (1593, 'after', r'''实现就三查：快照、注册表、会话存储，任一非空即真。与 hasInstructionsLoadedHook/hasWorktreeCreateHook 同款模式。'''),
    (1603, 'before', r'''getMatchingHooks：事件 → 匹配 hook 列表的完整管线。步骤：合并来源 → 按 matchQuery 过滤 matcher → 展开成 MatchedHook（带插件上下文）→ 按命令/提示/URL 去重 → if 条件过滤 → 事件特化过滤（SessionStart/Setup 禁 HTTP hook）。整体 try 包裹，任何异常静默返回空数组——hook 匹配失败不能拖垮主流程。'''),
    (1616, 'before', r'''matchQuery 按事件语义选取：工具事件用工具名；SessionStart 用 source；Setup/Compact 用 trigger；Notification 用类型；SessionEnd 用 reason；FileChanged 用文件名。hook 的 matcher 字段针对的就是这些值。'''),
    (1710, 'after', r'''展开阶段：每个 matcher 的 hooks 摊平成 MatchedHook，并标记 hookSource（plugin:名字 / skill:名字 / settings）供遥测与权限原因展示。'''),
    (1729, 'after', r'''快路径：全是 callback/function hook 时跳过去重（每个回调天然唯一），省掉下面 6 遍 filter + 4 组 Map/Array——内部 hook（sessionFileAccessHooks 等）都是这种形态，微基准快 44 倍。'''),
    (1806, 'after', r'''去重的身份定义：命令 hook 看 shell+命令+if 条件（shell 属于身份——同命令不同 shell 是两个 hook，缺省当 bash 使旧配置能与显式 bash 去重）；prompt/agent 看 prompt+if；http 看 url+if。注意 Map 重复键保留最后一条：settings 场景即后合并的 scope 胜出。'''),
    (1848, 'after', r'''if 条件过滤：条件无法求值（非工具事件）时该 hook 直接跳过并记调试日志——fail closed，宁可少跑不可误跑。'''),
    (1864, 'after', r'''事件特化过滤：SessionStart/Setup 禁 HTTP hook——headless 模式下沙箱询问回调会在结构化输入消费者启动前死锁。'''),
    (1874, 'after', r'''getMatchingHooks 收尾：返回过滤后的列表；整段 catch 空——hook 系统的任何配置错误都不允许影响正常会话。'''),
    (1887, 'after', r'''以下是一组格式化小函数：把阻塞错误渲染成给模型/用户看的文案。各自带事件前缀（PreToolUse hook error / Stop hook feedback 等）。'''),
    (1896, 'after', r'''Stop hook 的反馈格式：模型回合结束后被 hook 拦下时，这条文本作为反馈喂回模型让它继续。'''),
    (1940, 'after', r'''UserPromptSubmit 的阻塞文案：用户提交提示词被 hook 拦截时的展示文本。其余 TeammateIdle/TaskCreated/TaskCompleted 同款（省略）。'''),
    (1952, 'before', r'''executeHooks：REPL 内 hook 执行的总编排（async generator）。外围闸门 → 匹配 → 进度事件 → 并行执行各类型 hook → 聚合结果（退出码协议 + JSON 协议）→ 权限行为归并 → 统计遥测。调用方通过 yield 逐条拿结果。'''),
    (1999, 'after', r'''第一道闸：disableAllHooks 管理设置（含受管 hook 一起禁）与 CLAUDE_CODE_SIMPLE 模式直接返回。'''),
    (2013, 'after', r'''信任检查集中在这里（上面 shouldSkipHookDueToTrust）——注释明说是为了防 RCE：所有现在与未来的 hook 事件都过这一道。无匹配 hook 或已取消同样直接返回。'''),
    (2067, 'after', r'''内部回调快路径：全是 internal callback 时跳过 span/progress/abortSignal/JSON 处理/结果循环，直接调用回调（它们返回 {} 且不用取消信号）。实测每次 PostToolUse 命中从 6.01µs 降到 1.8µs（-70%）。'''),
    (2116, 'after', r'''执行前给每个 hook yield 一条 progress 事件——UI 上能看到「正在运行 hook: PreToolUse:Bash」。prompt hook 额外带提示原文，可自定义 statusMessage。'''),
    (2140, 'after', r'''getJsonInput 惰性单次序列化：同一批的命令/提示/代理/HTTP hook 共享一份 JSON（hookInput 不会被改）。纯回调批次在前面已返回，完全不付序列化成本。'''),
    (2192, 'after', r'''per-hook 执行器是个 async generator，按类型分派：callback 走 createCombinedAbortSignal（外层取消 + hook 自身超时合并）；function hook 必须有消息数组（来自会话存储的内嵌回调）。'''),
    (2224, 'before', r'''prompt/agent hook 的前置断言：两者都需要 ToolUseContext（提示 hook 要模型调用，代理 hook 还要消息历史），缺了直接抛「这是 bug」——编程错误不该被静默吞掉。'''),
    (2296, 'before', r'''HTTP hook 分支：execHttpHook 内部自管超时（hook.timeout 或默认 HTTP 超时），所以传原始 signal 而非合并后的 abortSignal——避免双层超时叠加。'''),
    (2444, 'after', r'''HTTP 分支的结果分诊：取消 → hook_cancelled；网络错误或非 2xx → non_blocking_error；JSON 校验失败 → non_blocking_error；async 响应 → 直接成功；合法 sync JSON → 走 processHookJSONOutput 翻译。'''),
    (2461, 'after', r'''命令 hook 主体：execCommandHook 返回后按 backgrounded/aborted 先行短路，剩下的进输出协议解析。'''),
    (2647, 'before', r'''退出码协议（非 JSON 输出的传统约定）：0 成功（stdout 展示）；2 阻塞（stderr 作为阻塞反馈喂回模型）；其他非零 = 非关键错误，只展示不阻塞。'''),
    (2697, 'after', r'''其他非零退出码：hook 自身崩了（脚本语法错、命令不存在等）不该连累会话——non_blocking_error 附件展示给用户，流程继续。'''),
    (2731, 'after', r'''per-hook 生成器的 catch：执行抛异常（如 JSON 输入序列化失败、prompt hook 断言）一律转成 non_blocking_error 附件，同时 emitHookResponse 把失败回执发给 SDK 侧监听者。'''),
    (2756, 'after', r'''结果聚合循环：all() 把 per-hook 生成器汇成单一流。preventContinuation 最先处理——hook 要求停止回合（continue:false），直接 yield 出去。'''),
    (2847, 'after', r'''权限行为归并优先级：deny > ask > allow。多个 hook 意见冲突时取最保守的——只要有一个拒绝就拒绝；ask 压过 allow；allow 只在没有任何其他意见时生效。passthrough 不参与。'''),
    (2868, 'after', r'''归并结果随每条 hook 即时 yield（updatedInput 仅在 allow/ask 时随权限行为带出）；另外 passthrough 情形（无权限决策）下 updatedInput 单独 yield——hook 可以只改入参不做权限表态。'''),
    (2928, 'after', r'''会话 hook 的成功回调：sessionFileAccessHooks 之外的会话注册 hook 若带 onHookSuccess 且结果成功，执行之；回调抛错只记日志不外泄。'''),
    (2944, 'after', r'''批级统计：总时长进 statsStore 直方图与回合级累计；tengu_repl_hook_finished 上报成功/阻塞/非阻塞错误/取消四类计数。'''),
    (2972, 'after', r'''executeHooks 收尾：beta 追踪开启时补 OTEL 完成事件并结束 hook span。'''),
    (2981, 'after', r'''HookOutsideReplResult：REPL 之外（通知、会话结束、压缩、worktree）hook 的简化结果——只有命令名、成败、输出、是否阻塞、watchPaths、systemMessage。'''),
    (2985, 'after', r'''hasBlockingResult：调用方判断这批外部 hook 是否有阻塞意见。'''),
    (3003, 'before', r'''executeHooksOutsideREPL：REPL 外的执行路径。与 executeHooks 的关键差异：没有消息数组和 ToolUseContext，所以 prompt/agent/function hook 不支持；结果不 yield 给模型，只 logForDebugging（--debug 可见），需要呈现的调用方自己处理（如 executeSessionEndHooks 在关机时写 stderr）。'''),
    (3150, 'after', r'''callback 分支：WorktreeCreate 特判——输出直接取 worktreePath（消费者把它当文件系统路径用）。block 判定同样看 JSON decision。'''),
    (3170, 'after', r'''prompt/agent hook 在 REPL 外不支持：直接返回失败结果（TODO 待实现），不会静默丢弃。'''),
    (3186, 'after', r'''function hook 在 REPL 外是内部错误：记 logError——function hook 只该出现在 REPL 语境（-p 模式的 Stop hook 走 executeStopHooks）。'''),
    (3279, 'after', r'''HTTP 分支收尾与 WorktreeCreate 特判：命令 hook 靠 stdout 提供 worktree 路径，HTTP hook 靠 hookSpecificOutput.worktreePath——没有就发空串，让消费者的长度过滤跳过，而不是把裸 {} 当路径。'''),
    (3334, 'after', r'''命令 hook 的阻塞判定：退出码 2 或 JSON decision: block，二者其一。成功取 stdout、失败取 stderr 作为输出——与 REPL 内一致的约定。'''),
    (3381, 'after', r'''executeHooksOutsideREPL 收尾：Promise.all 等全部完成。注意这里没有进度事件、没有遥测 span——外部路径尽量轻。'''),
    (3436, 'after', r'''executePreToolHooks：PreToolUse 事件入口。先用 hasHookForEvent 快速短路（绝大多数会话没配 hook，省掉 transcript 路径拼接），再组输入（含工具名/入参/toolUseID）委托 executeHooks。'''),
    (3477, 'after', r'''executePostToolHooks：PostToolUse 事件入口，多带 toolResponse（工具的返回结果，hook 可据此改写 MCP 输出）。'''),
    (3527, 'after', r'''executePostToolUseFailureHooks：工具调用失败后触发，带 error 文本与 is_interrupt（是否用户手动中断）。'''),
    (3562, 'after', r'''executePermissionDeniedHooks：权限被拒后触发，hook 可要求 retry 重试。'''),
    (3592, 'after', r'''executeNotificationHooks：通知事件（如等待输入、权限请求）走 REPL 外路径——通知不需要向模型注入任何东西。'''),
    (3627, 'after', r'''executeStopFailureHooks：回合因错误终止时触发。注意 3598-3603 的注释：executeHooksOutsideREPL 硬编码主会话 ID，若这里用 agentId 做门禁会出现「门禁过了但执行找不到 hook」的错位——所以门禁与执行对齐都用主会话 ID。error 缺省 unknown 保证 matcher 过滤照常生效。'''),
    (3653, 'after', r'''Stop 与 SubagentStop 共用一个入口：有 subagentId 就是子代理结束（额外带 agent_transcript_path 与 agent_type），否则是主回合结束。last_assistant_message 预提取文本，hook 无需自己读转录文件。'''),
    (3697, 'after', r'''executeStopHooks 收尾：stop_hook_active 标记「已在 Stop hook 内」，防模型被 Stop hook 反复拉起造成死循环。'''),
    (3729, 'after', r'''executeTeammateIdleHooks：队友要空闲时触发，阻塞（退出码 2）则队友继续干活不空闲。'''),
    (3773, 'after', r'''executeTaskCreatedHooks：任务创建前触发，阻塞可阻止建任务并返回反馈。'''),
    (3817, 'after', r'''executeTaskCompletedHooks：任务标记完成前触发，同款阻塞语义。'''),
    (3855, 'after', r'''executeUserPromptSubmitHooks：用户提交提示词后触发，additionalContext 可注入上下文；阻塞可整条拦下该提示。'''),
    (3892, 'after', r'''executeSessionStartHooks：会话启动（startup/resume/clear/compact 四种来源）触发，matchQuery 用 source 让 matcher 能按启动来源过滤。'''),
    (3922, 'after', r'''executeSetupHooks：init（新项目初始化）或 maintenance（维护）触发。'''),
    (3952, 'after', r'''executeSubagentStartHooks：子代理启动触发，matcher 对 agent_type。'''),
    (4025, 'after', r'''executePreCompactHooks：压缩前触发。多个成功 hook 的输出合并成 newCustomInstructions（空行连接）注入压缩上下文；每个 hook 的成败拼成 userDisplayMessage 给用户看。'''),
    (4089, 'after', r'''executePostCompactHooks：压缩后触发，只回 userDisplayMessage——压缩已完成，没有可阻塞的东西了。'''),
    (4141, 'after', r'''executeSessionEndHooks：关机/清屏路径。Ink 已卸载，失败的 hook 直接写 stderr；执行完清掉本会话的会话级 hook（防止 resume 后残留）。'''),
    (4192, 'after', r'''executePermissionRequestHooks：权限弹窗即将展示时触发——hook 可以编程式代答（allow/deny），这是无人值守自动化的关键钩子。'''),
    (4236, 'after', r'''policy_settings 特判：企业策略配置的变更 hook 照常触发（审计日志用），但阻塞结果一律忽略——策略变更绝不允许被 hook 拦下。'''),
    (4239, 'after', r'''executeConfigChangeHooks 收尾：settings/skills/commands 文件变化时由文件监听器触发，企业安全团队据此审计配置变更。'''),
    (4258, 'after', r'''executeEnvHooks：环境类事件（CwdChanged/FileChanged）共用——执行完立即使会话环境缓存失效，让下次 bash 派生重新收集 hook 写入的环境文件。'''),
    (4276, 'after', r'''executeCwdChangedHooks：工作目录变化触发，带新旧两个路径。'''),
    (4294, 'after', r'''executeFileChangedHooks：被监听文件变化/新增/删除触发。'''),
    (4320, 'after', r'''hasInstructionsLoadedHook：InstructionsLoaded 的轻量存在性检查——每个指令文件加载都要能调 hook，没配置就别构建输入。'''),
    (4369, 'after', r'''executeInstructionsLoadedHooks：CLAUDE.md 或 .claude/rules/*.md 装进上下文时触发，纯观测审计、不支持阻塞。三个派发点：会话启动急加载、压缩后重载（load_reason: compact）、触碰触发条件的嵌套 CLAUDE.md 时懒加载。'''),
    (4468, 'after', r'''parseElicitationHookOutput：从外部 hook 结果提取引导（elicitation）应答。阻塞判定与 executeHooks 一致（退出码 2 或 JSON block）；然后解析 hookSpecificOutput 里的 action/content；decline 额外构造 blockingError。事件名必须匹配预期（Elicitation 或 ElicitationResult），其他输出忽略。'''),
    (4523, 'after', r'''executeElicitationHooks：MCP 服务器发起引导（表单/URL）时触发，hook 可代答 accept/decline。多个 hook 时后解析的覆盖先前的。'''),
    (4575, 'after', r'''executeElicitationResultHooks：引导结果回报时触发（用户已答 accept/decline/cancel），同样可被 hook 代答或拦截。'''),
    (4666, 'after', r'''executeStatusLineCommand：状态栏命令——不是标准 hook 事件但复用 execCommandHook。超时仅 5 秒；禁用语义有层次：disableAllHooks 全禁；managed-only 时只跑策略层的 statusLine（非受管设置不能禁掉受管命令，但非受管命令被禁）。输出按行修剪重组。'''),
    (4738, 'after', r'''executeFileSuggestionCommand：文件输入建议（typeahead）辅助命令，同样 5 秒短超时，stdout 按行拆成路径数组。'''),
    (4757, 'after', r'''executeFunctionHook：函数型 hook——回调拿消息历史返回布尔，false 即阻塞（带自定义 errorMessage）。取消与超时经合并 AbortSignal 管理。'''),
    (4838, 'after', r'''executeFunctionHook 收尾：取消（消息匹配或 AbortError）返回 cancelled；真实异常转 non_blocking_error 附件。'''),
    (4896, 'after', r'''executeHookCallback：SDK 回调型 hook 的执行与结果翻译。回调没有 stdout/stderr/exitCode 概念，command 固定记 callback，事件名一致性校验照常。'''),
    (4920, 'after', r'''hasWorktreeCreateHook：存在性检查，必须镜像 getHooksConfig 的 managedOnly 过滤——否则这里返回 true 但执行时找不到 hook，git worktree 回退路径被误阻塞。'''),
    (4958, 'after', r'''executeWorktreeCreateHook：执行并取第一个成功输出的 worktree 路径；全部失败则抛错（汇总各命令的输出），调用方回落到内置 git worktree 逻辑。'''),
    (5003, 'after', r'''executeWorktreeRemoveHook：移除 worktree 时触发，返回「是否配置并执行了」；失败的 hook 只记日志——删除是收尾动作，不值得阻塞。'''),
    (5022, 'after', r'''文件末尾：getHookDefinitionsForTelemetry 把匹配的 hook 摘要成 {type, command/prompt/name} 数组供 beta 追踪。注意 command 与 http 都填 command 字段、function/callback 只有 name——遥测里无法区分 URL 与命令行之外的细节，这是刻意的脱敏。'''),
]
